// All-or-nothing runs of ops that write several times (schema apply): the
// work runs against an in-memory copy of the dataset, its mutations are
// recorded, and only once it finished without error are they replayed on
// the real store in ONE write. An error anywhere writes nothing.
// Ids generated by the work (newId) are part of the recorded mutations, so
// the replay produces exactly the documents the work saw.

import { createPluginRegistry } from "../core/pluginRegistry";
import { createMemoryStore } from "../data/memory";
import { COLLECTIONS, type DocMutation, type StoredDoc } from "../data/types";
import { createOpsContext, type OpsContext } from "./context";

export async function runStaged<T>(
  ctx: OpsContext,
  work: (staged: OpsContext) => Promise<T>,
  message: (result: T, mutations: DocMutation[]) => string,
): Promise<T> {
  const initial = Object.fromEntries(COLLECTIONS.map((c) => [c, ctx.store.list(c).map((d) => structuredClone(d) as StoredDoc)]));
  const copy = createMemoryStore({ initial, identity: null });
  await copy.ready();
  const recorded: DocMutation[] = [];
  const write = copy.write.bind(copy);
  copy.write = async (mutations, opts) => {
    recorded.push(...structuredClone(mutations));
    await write(mutations, opts);
  };
  // Isolated registry: the staged writes are not real, no plugin action
  // may see them (schema ops emit none today; keep it that way).
  const staged = createOpsContext(copy, ctx.user, { now: ctx.now, log: ctx.log, depth: ctx.depth, plugins: createPluginRegistry(() => undefined) });
  const result = await work(staged);
  copy.close?.();
  if (recorded.length) await ctx.store.write(recorded, { message: message(result, recorded) });
  return result;
}
